// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address callee, uint256 amount) public {
        amount = bound(amount, 1, 1e24);
        address target;
        if (callee.code.length == 0) {
            target = address(new Sink());
        } else {
            target = callee;
        }

        vm.deal(address(this), amount);
        (bool sent,) = address(c).call{value: amount}("");
        require(sent, "funding c failed");

        uint256 beforeBalance = address(c).balance;

        address attacker = address(0xBEEF);
        vm.deal(attacker, 1 wei);
        vm.prank(attacker);
        bool ok;
        try c.sendMoney(target, amount, "") { ok = true; } catch { ok = false; }

        uint256 afterBalance = address(c).balance;

        assertTrue(afterBalance >= beforeBalance);
    }
}

contract Sink {
    receive() external payable {}
}
